questions.solution:
class Tools:
    """One role's tools: a call outside the registry must be refused before it runs."""

    def __init__(self, role, repo, allowed):
        self.role, self.repo, self.allowed = role, repo, frozenset(allowed)

    def call(self, name, *args):
        if name not in self.allowed:
            raise PermissionError(f"{name} is not in the {self.role}'s registry")
        return getattr(self, "_" + name)(*args)

    def _read_file(self, path):
        return self.repo[path]

    def _write_file(self, path, text):
        self.repo[path] = text

    def _delete_file(self, path):
        del self.repo[path]

questions.tests:
repo = {"parse.py": "v1"}
gen = Tools("generator", repo, {"read_file", "write_file"})
ev = Tools("evaluator", repo, {"read_file"})

# 1. the generator may write, and both roles may read
gen.call("write_file", "parse.py", "v2")
assert ev.call("read_file", "parse.py") == "v2"

# 2. the evaluator's write is refused, and nothing was written
try:
    ev.call("write_file", "parse.py", "evaluator's fix")
    raise AssertionError("the evaluator wrote")
except PermissionError as exc:
    assert "write_file" in str(exc) and "evaluator" in str(exc)
assert repo == {"parse.py": "v2"}

# 3. any other tool outside the registry is refused too, before it runs
try:
    ev.call("delete_file", "parse.py")
    raise AssertionError("the evaluator deleted")
except PermissionError:
    pass
assert "parse.py" in repo

# 4. the generator cannot delete either: deletion is in nobody's registry here
try:
    gen.call("delete_file", "parse.py")
    raise AssertionError("the generator deleted")
except PermissionError:
    pass
assert repo == {"parse.py": "v2"}

# 5. a refused tool never runs at all, even if its effect could be undone afterwards
ran = []


class Spy(Tools):
    def _delete_file(self, path):
        ran.append(path)
        super()._delete_file(path)


try:
    Spy("evaluator", {"x": "1"}, {"read_file"}).call("delete_file", "x")
    raise AssertionError("the evaluator deleted")
except PermissionError:
    pass
assert ran == [], "the refused tool ran before the refusal"
print("all tests passed")
